const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
let currentUser = null, allProfiles = [], allMatches = [], allSwaps = [], authMode = 'register', toastTimer;
const palette = [['#eee9ff','#7258e8'],['#e0f8ed','#269d70'],['#ffede2','#d67d4b'],['#e3efff','#467fc3'],['#fce4f0','#c4558b']];
const initials = name => (name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const escapeHtml = value => String(value??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const skills = value => Array.isArray(value) ? value : [];
function showSiteLoader(title='Just a moment', message='Getting your SkillSwap experience ready…', foot='Preparing your workspace'){const el=$('#siteLoader');if(!el)return;el.style.display='grid';$('#loaderTitle').innerHTML=escapeHtml(title)+'<span>.</span>';$('#loaderMessage').textContent=message;$('#loaderFootText').textContent=foot;el.classList.remove('is-leaving');document.body.classList.add('is-booting')}
function hideSiteLoader(){const el=$('#siteLoader');if(!el)return;el.classList.add('is-leaving');document.body.classList.remove('is-booting');setTimeout(()=>{if(el.classList.contains('is-leaving'))el.style.display='none'},520)}
function toast(message, error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
async function api(path, options={}){const config={credentials:'include',cache:'no-store',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}};const res=await fetch(path,config);let data={};try{data=await res.json()}catch{}if(!res.ok){const err=new Error(data.error||(res.status===401?'Your login session has expired. Please log in again.':'Something went wrong. Please try again.'));err.status=res.status;throw err}return data}
function showView(name){const allowed=['overview','discover','matches','learning-path','skill-analyzer','feedback-analyzer','requests','collaborate','profile'];if(!allowed.includes(name))name='overview';$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#crumb').textContent=({overview:'Overview',discover:'Discover people',matches:'My matches','learning-path':'Learning Path','skill-analyzer':'Skill Analyzer','feedback-analyzer':'Feedback Analyzer',requests:'Skill exchanges',collaborate:'Collaborate',profile:'My profile'})[name];if(name==='discover')loadProfiles();if(name==='matches')loadMatches();if(name==='learning-path')loadLearningPathContext();if(name==='skill-analyzer')loadAnalyzerContext();if(name==='feedback-analyzer')loadFeedbackAnalysis();if(name==='requests')loadSwaps();if(name==='collaborate')loadCollaboration();if(name==='profile')renderProfile();window.scrollTo({top:0,behavior:'smooth'});document.body.classList.remove('mobile-nav-open');if($('#mobileMenuToggle'))$('#mobileMenuToggle').setAttribute('aria-expanded','false')}
function openModal(id){$('#'+id).classList.add('open')}function closeModal(id){$('#'+id).classList.remove('open')}
function openAuth(mode='register'){setAuthMode(mode);openModal('authModal')}
function setAuthMode(mode){authMode=mode;$$('[data-authmode]').forEach(b=>b.classList.toggle('active',b.dataset.authmode===mode));$('#registerFields').style.display=mode==='register'?'grid':'none';$('#registerFields').querySelectorAll('input').forEach(i=>i.required=mode==='register'&&['name','teach','learn'].includes(i.name));$('#authTitle').textContent=mode==='register'?'Create your skill profile':'Welcome back';$('#authSubtitle').textContent=mode==='register'?'Share your skills and find your people.':'Pick up where your learning journey left off.';$('#authSubmit').innerHTML=mode==='register'?'Create my profile <span>↗</span>':'Log in to SkillSwap <span>↗</span>';$('#authForm').elements.password.autocomplete=mode==='register'?'new-password':'current-password'}
function updateUserUI(){const logged=!!currentUser;$('#sideName').textContent=logged?currentUser.name:'Guest learner';$('#sideEmail').textContent=logged?currentUser.email:'Join the community';$('#sideAvatar').textContent=logged?initials(currentUser.name):'G';$('#topCta').textContent=logged?'Log out':'Get started';$('#topAuth').title=logged?'Log out':'Log in';$('#heroRegister').textContent=logged?'Edit my skill profile':'Create your skill profile';$('#bannerCta').textContent=logged?'Discover people':'Join SkillSwap';$('#statTeach').textContent=logged?skills(currentUser.teach).length:'—';$('#statLearn').textContent=logged?skills(currentUser.learn).length:'—';$('#statMatches').textContent=logged?allMatches.length:'—';$('#statSwaps').textContent=logged?allSwaps.filter(s=>['pending','accepted'].includes(s.status)).length:'—';$('#matchCount').textContent=logged?allMatches.length:'0';}
async function refreshMe(){try{const d=await api('/api/me');currentUser=d.user}catch{currentUser=null}updateUserUI()}
async function loadProfiles(){const grid=$('#profilesGrid');grid.innerHTML='<div class="empty-state">Finding your community…</div>';try{const q=$('#profileSearch').value.trim();const d=await api('/api/profiles'+(q?'?q='+encodeURIComponent(q):''));allProfiles=d.profiles||[];renderProfiles()}catch(e){grid.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`}}
function renderProfiles(){const grid=$('#profilesGrid');if(!allProfiles.length){grid.innerHTML='<div class="empty-state">No profiles found yet. Try another search or be the first to join the community. ✳</div>';return}grid.innerHTML=allProfiles.map((p,i)=>{const [bg,fg]=palette[i%palette.length];return `<article class="person-card"><div class="person-head"><div class="person-avatar" style="background:${bg};color:${fg}">${escapeHtml(initials(p.name))}</div><div><div class="person-name">${escapeHtml(p.name)}</div><div class="person-dept">${escapeHtml(p.department||'Curious learner')}</div></div></div><p class="person-bio">${escapeHtml(p.bio||'Ready to share knowledge, learn something new, and connect with the community.')}</p><div class="skill-label">CAN TEACH</div><div class="skill-tags">${skills(p.teach).slice(0,5).map(s=>`<span class="skill-tag">${escapeHtml(s)}</span>`).join('')||'<span class="skill-tag">Skills coming soon</span>'}</div><div class="skill-label">WANTS TO LEARN</div><div class="skill-tags">${skills(p.learn).slice(0,5).map(s=>`<span class="skill-tag learn">${escapeHtml(s)}</span>`).join('')||'<span class="skill-tag learn">Open to ideas</span>'}</div><div class="person-footer"><small>${p.id===currentUser?.id?'Your profile':'Knowledge worth sharing'}</small>${currentUser?`<button class="primary-button" data-swap-user="${p.id}" data-name="${escapeHtml(p.name)}" data-teach="${escapeHtml(skills(p.learn)[0]||'')}" data-learn="${escapeHtml(skills(p.teach)[0]||'')}">Propose swap ↗</button>`:`<button class="primary-button" data-auth-open="register">Connect ↗</button>`}</div></article>`}).join('');grid.querySelectorAll('[data-swap-user]').forEach(b=>b.addEventListener('click',()=>openSwap(b)));grid.querySelectorAll('[data-auth-open]').forEach(b=>b.addEventListener('click',()=>openAuth('login')))}
async function loadMatches(){const grid=$('#matchesGrid');if(!currentUser){grid.innerHTML='<div class="empty-state">Log in or create a profile to use AI Smart Match. <br><br><button class="primary-button" data-auth-open="register">Create my profile ↗</button></div>';grid.querySelector('button')?.addEventListener('click',()=>openAuth());return}grid.innerHTML='<div class="empty-state">AI is analysing member skills and ranking your best learning partners…</div>';try{const d=await api('/api/smart-matches');allMatches=d.matches||[];updateUserUI();renderMatches()}catch(e){grid.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`}}
function renderMatches(){const grid=$('#matchesGrid');if(!allMatches.length){grid.innerHTML='<div class="empty-state">No suitable recommendations yet. Add at least one skill you can teach and one you want to learn, and invite more learners to join SkillSwap. ✳<br><br><button class="primary-button" id="matchProfileBtn">Update my skills ↗</button></div>';$('#matchProfileBtn')?.addEventListener('click',()=>showView('profile'));return}grid.innerHTML=allMatches.map((m,i)=>{const p=m.user,[bg,fg]=palette[i%palette.length];const score=Math.max(0,Math.min(100,m.score||0));const teach=m.i_can_teach_them?.[0]||skills(currentUser.teach)[0]||'';const learn=m.they_can_teach_me?.[0]||skills(currentUser.learn)[0]||'';return `<article class="person-card smart-match-card"><div class="person-head"><div class="person-avatar" style="background:${bg};color:${fg}">${escapeHtml(initials(p.name))}</div><div><div class="person-name">${escapeHtml(p.name)}</div><div class="person-dept">${escapeHtml(p.department||'SkillSwap member')}</div></div><span class="match-badge">✦ AI RANK #${i+1}</span></div><div class="score-row"><div><strong>${score}%</strong><small>compatibility</small></div><div class="score-track"><span style="width:${score}%"></span></div></div><p class="person-bio">${m.match_type==='two-way'?'Two-way skill exchange found.':'Potential learning partner based on skill similarity.'}</p><div class="skill-label">THEY CAN TEACH YOU · ${m.learn_fit}% FIT</div><div class="skill-tags">${(m.they_can_teach_me||[]).map(s=>`<span class="skill-tag learn">${escapeHtml(s)}</span>`).join('')||'<span class="skill-tag learn">Related learning interests</span>'}</div><div class="skill-label">YOU CAN TEACH THEM · ${m.teach_fit}% FIT</div><div class="skill-tags">${(m.i_can_teach_them||[]).map(s=>`<span class="skill-tag">${escapeHtml(s)}</span>`).join('')||'<span class="skill-tag">Related teaching interests</span>'}</div><div class="match-reasons">${(m.reasons||[]).map(r=>`<span>✓ ${escapeHtml(r)}</span>`).join('')}</div><div class="person-footer"><small>TF-IDF + cosine similarity</small><button class="primary-button" data-match-swap="${p.id}" data-name="${escapeHtml(p.name)}" data-teach="${escapeHtml(teach)}" data-learn="${escapeHtml(learn)}">Start exchange ↗</button></div></article>`}).join('');grid.querySelectorAll('[data-match-swap]').forEach(openSwap)}
function openSwap(button){if(!currentUser){openAuth();return}const f=$('#swapForm');f.reset();f.elements.receiver_id.value=button.dataset.swapUser||button.dataset.matchSwap;f.elements.sender_teaches.value=button.dataset.teach||'';f.elements.sender_wants.value=button.dataset.learn||'';$('#swapTitle').textContent=`Connect with ${button.dataset.name||'your match'}.` ;$('#swapSubtitle').textContent='Offer one of your skills in exchange for something you want to learn.';openModal('swapModal')}
async function loadSwaps(){const list=$('#swapsList');if(!currentUser){list.innerHTML='<div class="empty-state">Log in to see and manage your skill exchanges.</div>';return}list.innerHTML='<div class="empty-state">Loading your exchanges…</div>';try{const d=await api('/api/swaps');allSwaps=d.swaps||[];updateUserUI();renderSwaps()}catch(e){list.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`}}
function renderSwaps(){const list=$('#swapsList');if(!allSwaps.length){list.innerHTML='<div class="empty-state">No exchanges yet. Your next great learning partnership is one match away. <br><br><button class="primary-button" id="findMatchBtn">Find a match ↗</button></div>';$('#findMatchBtn')?.addEventListener('click',()=>showView('matches'));return}list.innerHTML=allSwaps.map(s=>{const outgoing=s.sender_id===currentUser.id;const other=outgoing?s.receiver_name:s.sender_name;let actions='';if(s.can_respond)actions=`<button class="accept" data-swap-action="accepted" data-id="${s.id}">Accept</button><button data-swap-action="rejected" data-id="${s.id}">Decline</button>`;else if(outgoing&&['pending','accepted'].includes(s.status))actions=`<button data-swap-action="cancelled" data-id="${s.id}">Cancel</button>`;else if(s.status==='accepted')actions=`<button class="accept" data-swap-action="completed" data-id="${s.id}">Mark complete</button>`;return `<article class="swap-card"><div class="swap-symbol">⇄</div><div class="swap-info"><h3>${escapeHtml(other)} <span style="font-weight:500;color:#9998aa">· ${outgoing?'You sent a request':'Sent you a request'}</span></h3><p>You teach <b>${escapeHtml(s.sender_teaches)}</b> · You learn <b>${escapeHtml(s.sender_wants)}</b>${s.created_at?` · ${new Date(s.created_at).toLocaleDateString()}`:''}</p></div><span class="status ${escapeHtml(s.status)}">${escapeHtml(s.status)}</span><div class="swap-actions">${actions}</div></article>`}).join('');list.querySelectorAll('[data-swap-action]').forEach(b=>b.addEventListener('click',async()=>{try{await api(`/api/swaps/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.swapAction})});toast(`Exchange ${b.dataset.swapAction}.`);await loadSwaps()}catch(e){toast(e.message,true)}}))}
function renderProfile(){const panel=$('#profilePanel');if(!currentUser){panel.innerHTML='<div class="empty-state">Create an account or log in to edit your profile.<br><br><button class="primary-button" id="profileAuthBtn">Get started ↗</button></div>';$('#profileAuthBtn')?.addEventListener('click',()=>openAuth());return}panel.innerHTML=`<div class="profile-cover"></div><div class="profile-main"><div class="avatar">${escapeHtml(initials(currentUser.name))}</div><div><h2>${escapeHtml(currentUser.name)}</h2><p>${escapeHtml(currentUser.email)}</p><div class="skill-tags" style="margin-top:10px"><span class="skill-tag">Account #${escapeHtml(currentUser.id)}</span><span class="skill-tag learn">${currentUser.created_at ? 'Joined ' + escapeHtml(new Date(currentUser.created_at).toLocaleDateString()) : 'Registered member'}</span></div></div></div><div class="account-details"><div><small>ACCOUNT EMAIL</small><strong>${escapeHtml(currentUser.email)}</strong></div><div><small>DEPARTMENT / FIELD</small><strong>${escapeHtml(currentUser.department||'Not added yet')}</strong></div><div><small>ACCOUNT STATUS</small><strong>Active · Signed in</strong></div></div><form class="profile-form" id="profileEditForm"><label>Full name<input name="name" required maxlength="100" value="${escapeHtml(currentUser.name)}"></label><label>Department or field<input name="department" maxlength="120" value="${escapeHtml(currentUser.department||'')}" placeholder="e.g. Engineering, Marketing"></label><label>Short bio<textarea name="bio" maxlength="500" placeholder="Tell people what you enjoy learning or teaching…">${escapeHtml(currentUser.bio||'')}</textarea></label><div class="form-actions"><button class="primary-button" type="submit">Save profile changes <span>↗</span></button></div></form><div class="form-two skill-manage-grid" style="margin-top:22px"><div><div class="skill-label">SKILLS I CAN TEACH</div><div class="skill-tags">${skills(currentUser.teach).map(s=>`<span class="skill-tag skill-removable">${escapeHtml(s)} <button type="button" data-delete-skill="teach:${escapeHtml(s)}" aria-label="Remove ${escapeHtml(s)}">×</button></span>`).join('')||'—'}</div></div><div><div class="skill-label">SKILLS I WANT TO LEARN</div><div class="skill-tags">${skills(currentUser.learn).map(s=>`<span class="skill-tag learn skill-removable">${escapeHtml(s)} <button type="button" data-delete-skill="learn:${escapeHtml(s)}" aria-label="Remove ${escapeHtml(s)}">×</button></span>`).join('')||'—'}</div></div></div><form id="addSkillForm" class="add-skill-form"><label>Add a skill<input name="name" maxlength="80" required placeholder="e.g. Excel, public speaking"></label><label>Skill type<select name="kind"><option value="teach">I can teach this</option><option value="learn">I want to learn this</option></select></label><button class="primary-button" type="submit">Add skill <span>＋</span></button></form><p style="font-size:10px;color:#9b9aae;margin-top:12px">Skills are saved to your account and used for matching.</p>`;$('#profileEditForm').addEventListener('submit',saveProfile)}
async function saveProfile(e){e.preventDefault();const f=e.currentTarget;try{const d=await api('/api/me',{method:'PUT',body:JSON.stringify({name:f.elements.name.value,department:f.elements.department.value,bio:f.elements.bio.value})});currentUser=d.user;updateUserUI();renderProfile();toast('Profile updated successfully.')}catch(e){toast(e.message,true)}}
$('#authForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const data={email:f.elements.email.value.trim(),password:f.elements.password.value};if(authMode==='register'){data.name=f.elements.name.value.trim();data.department=f.elements.department.value.trim();data.teach=f.elements.teach.value.split(',').map(s=>s.trim()).filter(Boolean);data.learn=f.elements.learn.value.split(',').map(s=>s.trim()).filter(Boolean);if(!data.teach.length||!data.learn.length){toast('Add at least one skill to teach and one to learn.',true);return}}const submit=$('#authSubmit');submit.disabled=true;submit.classList.add('is-loading');submit.textContent=authMode==='register'?'Creating your profile…':'Logging in…';showSiteLoader(authMode==='register'?'Building your profile':'Welcome back','Securely signing you in and preparing your learning space…',authMode==='register'?'Creating your SkillSwap account':'Verifying your account');try{const d=await api(authMode==='register'?'/api/register':'/api/login',{method:'POST',body:JSON.stringify(data)});currentUser=d.user;closeModal('authModal');f.reset();await Promise.all([loadMatches(),loadSwaps()]);updateUserUI();toast(authMode==='register'?'Welcome to SkillSwap! Your profile is ready.':'Welcome back!');if(authMode==='register')showView('profile')}catch(err){toast(err.message,true)}finally{hideSiteLoader();submit.disabled=false;submit.classList.remove('is-loading');submit.innerHTML=authMode==='register'?'Create my profile <span>↗</span>':'Log in to SkillSwap <span>↗</span>'}});
$('#swapForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;try{await api('/api/swaps',{method:'POST',body:JSON.stringify({receiver_id:f.elements.receiver_id.value,sender_teaches:f.elements.sender_teaches.value.trim(),sender_wants:f.elements.sender_wants.value.trim()})});closeModal('swapModal');toast('Exchange request sent!');await loadSwaps();showView('requests')}catch(err){toast(err.message,true);if(err.status===401){await refreshMe();openAuth('login')}}});
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));$$('[data-open-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.openView)));const mobileMenu=$('#mobileMenuToggle'),sidebarScrim=$('#sidebarScrim');function setMobileNav(open){document.body.classList.toggle('mobile-nav-open',open);if(mobileMenu)mobileMenu.setAttribute('aria-expanded',String(open));if(mobileMenu)mobileMenu.setAttribute('aria-label',open?'Close navigation':'Open navigation')}if(mobileMenu)mobileMenu.addEventListener('click',()=>setMobileNav(!document.body.classList.contains('mobile-nav-open')));if(sidebarScrim)sidebarScrim.addEventListener('click',()=>setMobileNav(false));$$('[data-nav]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();showView(b.dataset.nav)}));$$('[data-close]').forEach(b=>b.addEventListener('click',()=>closeModal(b.dataset.close)));$$('.modal-backdrop').forEach(b=>b.addEventListener('click',e=>{if(e.target===b)b.classList.remove('open')}));$$('[data-authmode]').forEach(b=>b.addEventListener('click',()=>setAuthMode(b.dataset.authmode)));
$('#topCta').addEventListener('click',async()=>{if(currentUser){try{await api('/api/logout',{method:'POST'});currentUser=null;allMatches=[];allSwaps=[];if(pollTimer)clearInterval(pollTimer);collabSwaps=[];activeSwapId=null;updateUserUI();toast('You have logged out.');showView('overview')}catch(e){toast(e.message,true)}}else openAuth()});$('#topAuth').addEventListener('click',()=>currentUser?$('#topCta').click():openAuth('login'));$('#sideAuth').addEventListener('click',()=>currentUser?$('#topCta').click():openAuth());$('#heroDiscover').addEventListener('click',()=>showView('discover'));$('#heroRegister').addEventListener('click',()=>currentUser?showView('profile'):openAuth());$('#bannerCta').addEventListener('click',()=>currentUser?showView('discover'):openAuth());$('#howBtn').addEventListener('click',()=>showView('overview'));$('#footerHow').addEventListener('click',e=>{e.preventDefault();showView('overview');$('#view-overview .section-heading').scrollIntoView({behavior:'smooth'})});$('#profileSearch').addEventListener('input',()=>{clearTimeout(window.searchDebounce);window.searchDebounce=setTimeout(loadProfiles,250)});$('#clearSearch').addEventListener('click',()=>{$('#profileSearch').value='';loadProfiles()});

// Profile skill management uses the authenticated Flask API.
document.addEventListener('submit', async e=>{
  if(e.target.id==='addSkillForm'){
    e.preventDefault(); if(!currentUser){openAuth();return}
    const f=e.target, name=f.elements.name.value.trim(), kind=f.elements.kind.value;
    try{await api('/api/skills',{method:'POST',body:JSON.stringify({name,kind,category:'Other'})});await refreshMe();renderProfile();await loadMatches();toast('Skill added to your profile.')}catch(err){toast(err.message,true)}
  }
});
document.addEventListener('click', async e=>{
  const btn=e.target.closest('[data-delete-skill]'); if(!btn)return;
  if(!currentUser)return;
  const [kind,name]=btn.dataset.deleteSkill.split(':',2);
  const skill=(currentUser.skills||[]).find(x=>x.kind===kind&&x.name===name);
  // Public user payload intentionally contains only skill names; find the ID through the skills API.
  try{const d=await api('/api/skills?kind='+encodeURIComponent(kind));const item=(d.skills||[]).find(x=>x.user_id===currentUser.id&&x.skill.toLowerCase()===name.toLowerCase());if(!item)throw new Error('Could not find that skill. Refresh the page and try again.');await api('/api/skills/'+item.id,{method:'DELETE'});await refreshMe();renderProfile();await loadMatches();toast('Skill removed from your profile.')}catch(err){toast(err.message,true)}
});

// SkillBuddy robot companion: persistent helper, lightweight local preferences and friendly reactions.
const petWidget=$('#assistantWidget'), assistantPanel=$('#assistantPanel'), assistantMessages=$('#assistantMessages');
const petStore={get(k,fallback=''){try{return localStorage.getItem('skillswap_pet_'+k)||fallback}catch(_){return fallback}},set(k,v){try{localStorage.setItem('skillswap_pet_'+k,v)}catch(_){}}};
let petName=petStore.get('name','SkillBuddy'), petBubbleTimer=null;
function setPetName(name){petName=String(name||'SkillBuddy').trim().replace(/[<>]/g,'').slice(0,18)||'SkillBuddy';petStore.set('name',petName);$('#assistantPetName').textContent=petName;$('#petToggleName').textContent=petName;$('#petGreeting').textContent=`Hey${currentUser?.name?' '+currentUser.name:''}! I'm ${petName}. 👋`;}
setPetName(petName);
function petBubble(message,show=true){const bubble=$('#petSpeech');if(!bubble)return;bubble.innerHTML=`${escapeHtml(message)} <span>✦</span>`;bubble.classList.toggle('show',show);clearTimeout(petBubbleTimer);if(show)petBubbleTimer=setTimeout(()=>bubble.classList.remove('show'),6500)}
function petMood(mood='idle',status='Your friendly learning companion'){petWidget.classList.remove('pet-happy','pet-thinking','pet-sleepy');if(mood!=='idle')petWidget.classList.add('pet-'+mood);$('#petStatusLine').textContent=status;}
function toggleAssistant(force){const open=typeof force==='boolean'?force:!assistantPanel.classList.contains('open');assistantPanel.classList.toggle('open',open);assistantPanel.setAttribute('aria-hidden',String(!open));$('#assistantToggle').setAttribute('aria-expanded',String(open));if(open){petBubble('',false);petMood('happy','Ready to help you learn!');setTimeout(()=>$('#assistantInput').focus(),100)}else{petMood('idle');}}
function addChatMessage(text,who='bot',actionLabel='',actionView=''){
  const msg=document.createElement('div');msg.className='chat-message '+who;msg.textContent=text;
  if(actionLabel&&actionView){const b=document.createElement('button');b.type='button';b.textContent=actionLabel;b.addEventListener('click',()=>{toggleAssistant(false);if(actionView==='auth')openAuth();else showView(actionView)});msg.appendChild(document.createElement('br'));msg.appendChild(b)}
  assistantMessages.appendChild(msg);assistantMessages.scrollTop=assistantMessages.scrollHeight;
  if(who==='bot'){petMood('happy','I found something helpful for you');}
  try{const history=JSON.parse(petStore.get('history','[]'));history.push({text:String(text).slice(0,600),who});petStore.set('history',JSON.stringify(history.slice(-18)))}catch(_){}
}
function restorePetChat(){try{const history=JSON.parse(petStore.get('history','[]'));if(!Array.isArray(history)||!history.length)return;assistantMessages.innerHTML='';history.slice(-12).forEach(m=>{const el=document.createElement('div');el.className='chat-message '+(m.who==='user'?'user':'bot');el.textContent=String(m.text||'').slice(0,600);assistantMessages.appendChild(el)});assistantMessages.scrollTop=assistantMessages.scrollHeight}catch(_){}}
restorePetChat();
function assistantAnswer(question){const q=question.toLowerCase();if(/create|register|sign up|account/.test(q))return {text:currentUser?`You're already signed in as ${currentUser.name}. You can edit your profile or log out from the top-right button.`:'To create an account, choose “Get started” or “Create your skill profile”. Enter your name, email, a password of at least 8 characters, and at least one skill to teach and one to learn.',label:currentUser?'Open my profile':'Create an account',view:currentUser?'profile':'auth'};if(/log ?in|password|sign ?in/.test(q))return {text:'Choose “Get started”, then select “Log in”. Use the same email and password you registered with. Never share your password in chat.',label:'Open login',view:'auth'};if(/match|find people|discover|mentor|partner/.test(q))return {text:currentUser?'Open Discover people to search by name, skill, or department. Smart Match ranks two-way matches using the skills people offer and want to learn.':'Create an account or log in first, then add both teach and learn skills. After that, open Discover people or Smart Match.',label:'Find a partner',view:'discover'};if(/chat|message|video|meeting|resource|file|project|task|collaborat/.test(q))return {text:currentUser?'Open Collaborate after your exchange request has been accepted. You can privately message your partner, share links/files, start a video meeting, create a project, assign tasks, and leave feedback.':'Log in, send a skill exchange request, and wait for the partner to accept it. Then open Collaborate to chat, share resources, use video meetings, and work together.',label:'Open collaboration',view:'collaborate'};if(/exchange|request|accept|decline|cancel|complete|swap/.test(q))return {text:'Open a person card and choose “Propose swap”. Choose the skill you will teach and the skill you want to learn, then send the request. Manage incoming requests in Skill exchanges.',label:'Open skill exchanges',view:'requests'};if(/profile|bio|department|edit|skill list|add skill|remove skill/.test(q))return {text:currentUser?'Open My profile to edit your name, department, bio, and teach/learn skills. Your skills help the matching engine recommend people.':'Log in first, then open My profile to manage your skills.',label:'Open my profile',view:'profile'};if(/learning path|roadmap|what.*learn|learn next|study plan/.test(q))return {text:'Tell the Learning Path planner what you want to learn, your experience level, how many weeks you have, and your weekly study time. It will create a week-by-week roadmap.',label:'Open Learning Path',view:'learning-path'};if(/analy[sz]|skill gap|missing skill|strength/.test(q))return {text:'The Skill Analyzer compares your current skills with a selected role or goal. It highlights strengths, gaps and suggested next steps.',label:'Open Skill Analyzer',view:'skill-analyzer'};if(/feedback|review|sentiment/.test(q))return {text:'Feedback Analyzer summarises reviews you receive after completed exchanges and identifies sentiment and recurring themes.',label:'Open Feedback Analyzer',view:'feedback-analyzer'};if(/sad|unmotivated|tired|stress|motivat|bad day|lonely/.test(q))return {text:'A little progress is still progress. 💜 You do not need to master everything today. Pick one tiny task for 10 minutes, or take a proper break if you need one. Want me to help choose a small learning step?',label:'Plan a small step',view:'learning-path'};if(/how|start|work|step|guide|help/.test(q))return {text:'SkillSwap has three steps: 1) Create a profile with skills you can teach and want to learn. 2) Discover people and check Smart Match. 3) Send a skill exchange request, agree on a plan, and learn together. I can also guide you through the AI Lab tools.',label:'See how it works',view:'overview'};return {text:'I can help with profiles, finding partners, skill exchanges, collaboration, learning plans and the AI Lab. Try asking “What should I learn next?” or “Find me a Python partner”.',label:'Explore SkillSwap',view:'overview'}}
async function askSkillBuddy(question){const q=String(question||'').trim();if(!q)return;addChatMessage(q,'user');$('#assistantInput').value='';const fallback=assistantAnswer(q);petMood('thinking','Thinking of a helpful answer…');try{const history=(()=>{try{return JSON.parse(petStore.get('history','[]')).slice(-9,-1).slice(-8).map(m=>({role:m.who==='user'?'user':'assistant',content:m.text}));}catch(_){return [];}})();const result=await api('/api/assistant',{method:'POST',body:JSON.stringify({question:q,history})});const answer=result.answer||fallback.text;addChatMessage(answer,'bot',fallback.label,fallback.view);if(result.mode!=='ai'&&/unmotivated|sad|tired|stress|motivat/.test(q.toLowerCase()))petBubble('You have got this. One small step!');}
  catch(_){addChatMessage(fallback.text,'bot',fallback.label,fallback.view)}finally{petMood('idle');}}
$('#assistantToggle').addEventListener('click',()=>toggleAssistant());$('#assistantClose').addEventListener('click',()=>toggleAssistant(false));$('#assistantForm').addEventListener('submit',e=>{e.preventDefault();askSkillBuddy($('#assistantInput').value)});$('#assistantQuick').querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>askSkillBuddy(b.dataset.question)));
$('#petRename').addEventListener('click',()=>{const value=prompt('What would you like to name your robot friend?',petName);if(value!==null){setPetName(value);petBubble(`Yay! You can call me ${petName}.`);}});
$('#petCheer').addEventListener('click',()=>{const cheers=['You are doing better than you think. Keep going! 💜','Tiny steps become big achievements. I believe in you!','Your skills are worth sharing. Someone can learn from you today!','Take a breath, choose one small goal, and let us tackle it together.'];const cheer=cheers[Math.floor(Math.random()*cheers.length)];petMood('happy','Sending you a little encouragement');petBubble(cheer);addChatMessage(cheer,'bot');});
$('#petTip').addEventListener('click',()=>{const tips=['Try teaching a concept you learned today. Explaining it helps you remember.','Break a big learning goal into a 20-minute task.','Ask a learning partner to review one small project.','Update your teach and learn skills so Smart Match can find better partners.','Consistency beats cramming: a little practice each day adds up.'];const tip=tips[new Date().getDate()%tips.length];addChatMessage('💡 Daily learning tip: '+tip,'bot');petBubble('I brought you a tiny learning tip!');});
async function refreshAssistantMode(){const label=$('#assistantModeLabel'),foot=$('#assistantFootMode');try{const status=await api('/api/assistant/status');if(status.ai_enabled){label.textContent='AI-powered · '+(status.model||'OpenAI');label.classList.add('ai');label.classList.remove('builtin');foot.textContent='AI-powered responses enabled';}else{label.textContent='Built-in guide';label.classList.add('builtin');label.classList.remove('ai');foot.textContent='Built-in help active · add an API key for open-ended AI chat';}}catch(_){label.textContent='SkillSwap guide';foot.textContent='Website guidance available';}}
refreshAssistantMode();
// Friendly, occasional speech bubbles; never interrupt an open conversation.
const petGreetings=['Need help finding your next skill?','Psst… I can help you find a learning partner.','Ready for a tiny learning challenge?','I am right here if you get stuck.'];
setTimeout(()=>{if(!assistantPanel.classList.contains('open'))petBubble(petGreetings[0]);},4500);
setInterval(()=>{if(!assistantPanel.classList.contains('open')&&document.visibilityState==='visible')petBubble(petGreetings[Math.floor(Math.random()*petGreetings.length)]);},55000);
document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal-backdrop.open').forEach(m=>m.classList.remove('open'))});
// Collaboration workspace: private exchange chat, shared resources, project tasks, video room and feedback.
let collabSwaps=[], activeSwapId=null, lastMessageId=0, pollTimer=null, currentProject=null;
const collabEsc = value => escapeHtml(String(value ?? ''));
function activeSwap(){return collabSwaps.find(s=>String(s.id)===String(activeSwapId));}
async function loadCollaboration(){
  if(!currentUser){$('#collabSwapSelect').innerHTML='<option value="">Log in to collaborate</option>';$('#collabEmpty').hidden=false;$('#collabWorkspace').hidden=true;$('#collabEmpty').textContent='Log in, accept a skill exchange, and your collaboration space will appear here.';return;}
  try{const d=await api('/api/collaboration/swaps');collabSwaps=d.swaps||[];const select=$('#collabSwapSelect');const previous=activeSwapId;select.innerHTML=collabSwaps.length?collabSwaps.map(s=>`<option value="${s.id}">${collabEsc(s.peer_name)} — ${collabEsc(s.sender_teaches)} ↔ ${collabEsc(s.sender_wants)} (${s.status})</option>`).join(''):'<option value="">No accepted exchanges yet</option>';
    if(collabSwaps.length){activeSwapId=collabSwaps.some(s=>String(s.id)===String(previous))?previous:collabSwaps[0].id;select.value=String(activeSwapId);$('#collabEmpty').hidden=true;$('#collabWorkspace').hidden=false;$('#videoCallBtn').disabled=false;await loadActiveCollaboration();}
    else{activeSwapId=null;$('#collabEmpty').hidden=false;$('#collabWorkspace').hidden=true;$('#collabEmpty').textContent='Accept a skill exchange request first. Open Skill exchanges to accept a pending request, then come back here.';$('#videoCallBtn').disabled=true;}
  }catch(e){$('#collabEmpty').hidden=false;$('#collabEmpty').textContent=e.message;$('#collabWorkspace').hidden=true;}
}
async function loadActiveCollaboration(){const sw=activeSwap();if(!sw)return;$('#chatPartnerTitle').textContent='Chat with '+sw.peer_name;lastMessageId=0;$('#messageList').innerHTML='';if(pollTimer)clearInterval(pollTimer);await Promise.all([pollMessages(),loadResources(),loadProject(),loadFeedback()]);pollTimer=setInterval(()=>pollMessages().catch(()=>{}),2500);}
async function pollMessages(){if(!activeSwapId||document.hidden)return;const d=await api(`/api/swaps/${activeSwapId}/messages?after=${lastMessageId}`);const list=$('#messageList');for(const m of (d.messages||[])){lastMessageId=Math.max(lastMessageId,m.id);const el=document.createElement('div');el.className='message-bubble '+(m.sender_id===currentUser?.id?'mine':'theirs');const name=document.createElement('strong');name.textContent=m.sender_id===currentUser?.id?'You':m.sender_name;const body=document.createElement('p');body.textContent=m.body;const time=document.createElement('small');time.textContent=new Date(m.created_at).toLocaleString();el.append(name,body,time);list.appendChild(el);}if((d.messages||[]).length)list.scrollTop=list.scrollHeight;}
$('#collabSwapSelect').addEventListener('change',async e=>{activeSwapId=e.target.value||null;if(pollTimer)clearInterval(pollTimer);if(activeSwapId)await loadActiveCollaboration();});
$('#messageForm').addEventListener('submit',async e=>{e.preventDefault();if(!activeSwapId)return;const input=$('#messageInput');const body=input.value.trim();if(!body)return;try{await api(`/api/swaps/${activeSwapId}/messages`,{method:'POST',body:JSON.stringify({body})});input.value='';await pollMessages();}catch(err){toast(err.message,true)}});
async function loadResources(){const d=await api(`/api/swaps/${activeSwapId}/resources`);const list=$('#resourceList');const rows=d.resources||[];list.innerHTML=rows.length?rows.map(r=>`<div class="resource-item"><span class="resource-icon">${r.filename?'📎':'↗'}</span><div><strong>${collabEsc(r.title)}</strong><small>Shared by ${collabEsc(r.uploader_name)}</small><div>${r.url?`<a href="${collabEsc(r.url)}" target="_blank" rel="noopener noreferrer">Open link ↗</a>`:''} ${r.download_url?`<a href="${r.download_url}">Download file ↓</a>`:''}</div></div></div>`).join(''):'<p class="muted">No resources shared yet.</p>';}
$('#resourceForm').addEventListener('submit',async e=>{e.preventDefault();if(!activeSwapId)return;const f=e.currentTarget;const fd=new FormData(f);try{const res=await fetch(`/api/swaps/${activeSwapId}/resources`,{method:'POST',credentials:'same-origin',body:fd});const d=await res.json();if(!res.ok)throw new Error(d.error||'Could not share resource.');f.reset();await loadResources();toast('Resource shared with your exchange partner.');}catch(err){toast(err.message,true)}});
async function loadProject(){const d=await api(`/api/swaps/${activeSwapId}/project`);currentProject=d.project;renderProject();}
function renderProject(){const area=$('#projectArea');if(!currentProject){area.innerHTML=`<p class="muted">Turn your learning goals into a shared mini-project. Create tasks and assign them to either exchange member.</p><form id="createProjectForm" class="stack-form"><label>Project name<input name="title" maxlength="160" required placeholder="e.g. Build an electrical load calculator"></label><label>Project goal<textarea name="description" maxlength="2000" placeholder="What will you build or practice together?"></textarea></label><button class="primary-button" type="submit">Create project ↗</button></form>`;$('#createProjectForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;try{const d=await api(`/api/swaps/${activeSwapId}/project`,{method:'POST',body:JSON.stringify({title:f.elements.title.value,description:f.elements.description.value})});currentProject=d.project;renderProject();toast('Collaborative project created.');}catch(err){toast(err.message,true)}});return;}
 const sw=activeSwap();area.innerHTML=`<h3>${collabEsc(currentProject.title)}</h3><p>${collabEsc(currentProject.description||'No project description yet.')}</p><div class="task-list">${currentProject.tasks.length?currentProject.tasks.map(t=>`<div class="task-row"><div><strong>${collabEsc(t.title)}</strong><small>${collabEsc(t.details)} · Assigned to ${collabEsc(t.assignee_name)} ${t.due_date?'· Due '+collabEsc(t.due_date):''}</small></div><select data-task-status="${t.id}" aria-label="Task status"><option value="todo" ${t.status==='todo'?'selected':''}>To do</option><option value="doing" ${t.status==='doing'?'selected':''}>In progress</option><option value="done" ${t.status==='done'?'selected':''}>Done</option></select></div>`).join(''):'<p class="muted">No tasks yet. Add the first task below.</p>'}</div><form id="createTaskForm" class="stack-form task-form"><label>Task title<input name="title" maxlength="200" required placeholder="e.g. Draft the circuit diagram"></label><label>Details<input name="details" maxlength="1000" placeholder="What needs to be done?"></label><div class="form-two"><label>Assign to<select name="assignee_id"><option value="${currentUser.id}">Me</option><option value="${sw.peer_id}">${collabEsc(sw.peer_name)}</option></select></label><label>Due date<input name="due_date" type="date"></label></div><button class="secondary-button" type="submit">＋ Add task</button></form>`;
 area.querySelectorAll('[data-task-status]').forEach(sel=>sel.addEventListener('change',async()=>{try{await api(`/api/tasks/${sel.dataset.taskStatus}`,{method:'PATCH',body:JSON.stringify({status:sel.value})});await loadProject();}catch(err){toast(err.message,true)}}));$('#createTaskForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;try{await api(`/api/projects/${currentProject.id}/tasks`,{method:'POST',body:JSON.stringify({title:f.elements.title.value,details:f.elements.details.value,assignee_id:Number(f.elements.assignee_id.value),due_date:f.elements.due_date.value})});await loadProject();toast('Task added.');}catch(err){toast(err.message,true)}});
}
$('#videoCallBtn').addEventListener('click',async()=>{if(!activeSwapId)return;const room=`skillswap-exchange-${activeSwapId}`;const url=`https://meet.jit.si/${room}`;try{await api(`/api/swaps/${activeSwapId}/messages`,{method:'POST',body:JSON.stringify({body:`Video meeting invitation: ${url}\nOpen this link at the agreed time to join our exchange room.`})});await pollMessages();}catch(err){toast(err.message,true);return;}window.open(url,'_blank','noopener');toast('Meeting link sent in your private chat.');});
async function loadFeedback(){const sw=activeSwap();const area=$('#feedbackArea');if(!sw)return;if(sw.status!=='completed'){area.innerHTML='<p class="muted">Mark this exchange complete in Skill exchanges to leave feedback.</p>';return;}area.innerHTML=`<form id="feedbackForm" class="stack-form"><label>Rating<select name="rating"><option value="5">★★★★★ — Excellent</option><option value="4">★★★★ — Very good</option><option value="3">★★★ — Good</option><option value="2">★★ — Needs improvement</option><option value="1">★ — Poor</option></select></label><label>Comments<textarea name="comment" maxlength="1000" placeholder="What did you learn together?"></textarea></label><button class="primary-button" type="submit">Submit feedback</button></form><p class="muted small-note">One review per exchange.</p>`;$('#feedbackForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;try{await api(`/api/swaps/${activeSwapId}/feedback`,{method:'POST',body:JSON.stringify({rating:Number(f.elements.rating.value),comment:f.elements.comment.value})});area.innerHTML='<p class="success-note">Thanks! Your feedback has been saved.</p>';toast('Feedback submitted.');}catch(err){toast(err.message,true)}});}

async function loadLearningPathContext(){
  const box=$('#learningProfileContext');
  if(!currentUser){box.textContent='Log in to generate a roadmap personalised with your profile skills.';return;}
  const teach=skills(currentUser.teach), learn=skills(currentUser.learn);
  box.innerHTML=`<strong>Using your SkillSwap profile</strong><span>Can teach: ${teach.length?teach.map(escapeHtml).join(', '):'Not added yet'}</span><span>Want to learn: ${learn.length?learn.map(escapeHtml).join(', '):'Not added yet'}</span>`;
}
function renderLearningPath(roadmap){
  const out=$('#learningPathOutput');
  const weeks=(roadmap.weeks||[]).map(w=>`<article class="roadmap-week"><div class="roadmap-week-number">WEEK ${w.week}</div><div class="roadmap-week-content"><h3>${escapeHtml(w.title)}</h3><div class="roadmap-topics">${(w.topics||[]).map(t=>`<span>${escapeHtml(t)}</span>`).join('')}</div><strong>What you will do</strong><ul>${(w.tasks||[]).map(t=>`<li>${escapeHtml(t)}</li>`).join('')}</ul><div class="roadmap-deliverable"><b>Weekly output:</b> ${escapeHtml(w.deliverable||'Practical exercise')}</div></div></article>`).join('');
  const milestones=(roadmap.milestones||[]).map(m=>`<div class="roadmap-milestone"><span>WEEK ${m.at_week}</span><div><strong>${escapeHtml(m.label)}</strong><p>${escapeHtml(m.detail)}</p></div></div>`).join('');
  out.innerHTML=`<div class="roadmap-summary"><div class="eyebrow">YOUR PERSONALISED PLAN</div><h2>${escapeHtml(roadmap.goal)}</h2><p>${escapeHtml(roadmap.summary)}</p><div class="roadmap-stats"><div><strong>${roadmap.duration_weeks}</strong><span>weeks</span></div><div><strong>${roadmap.hours_per_week}</strong><span>hours / week</span></div><div><strong>${roadmap.estimated_total_hours}</strong><span>total hours</span></div><div><strong>${escapeHtml(roadmap.level)}</strong><span>level</span></div></div><p class="roadmap-personalisation">✦ ${escapeHtml(roadmap.personalisation)}</p></div><section class="roadmap-section"><div class="roadmap-section-heading"><div><div class="eyebrow">STEP-BY-STEP PLAN</div><h2>Your weekly roadmap</h2></div><button type="button" class="secondary-button" id="printRoadmapBtn">Print / Save PDF ↗</button></div><div class="roadmap-weeks">${weeks}</div></section><section class="roadmap-section roadmap-checkpoints"><div class="eyebrow">TRACK YOUR PROGRESS</div><h2>Milestones</h2>${milestones}</section><section class="roadmap-capstone"><div class="eyebrow">FINAL OUTCOME</div><h2>Capstone project</h2><p>${escapeHtml(roadmap.capstone)}</p><div class="roadmap-study-advice">${escapeHtml(roadmap.study_advice)}</div></section><div class="roadmap-engine-note"><strong>AI / algorithm used:</strong> ${escapeHtml(roadmap.algorithm)}. The roadmap is generated from the submitted goal, selected level, schedule and your SkillSwap profile context; it is not a fixed sample plan.</div>`;
  $('#printRoadmapBtn')?.addEventListener('click',()=>window.print());
}
$('#learningPathForm')?.addEventListener('submit',async e=>{
  e.preventDefault();
  if(!currentUser){toast('Please log in to generate your personalised learning path.',true);openAuth('login');return;}
  const form=e.currentTarget, btn=$('#generatePathBtn'), out=$('#learningPathOutput');
  btn.disabled=true;btn.textContent='Building your roadmap…';out.innerHTML='<div class="learning-empty"><span class="learning-spinner">✧</span><h2>Personalising your plan</h2><p>Sequencing topics and balancing your weekly study time…</p></div>';
  try{const fd=new FormData(form);const d=await api('/api/learning-path',{method:'POST',body:JSON.stringify({goal:fd.get('goal'),level:fd.get('level'),weeks:Number(fd.get('weeks')),hours_per_week:Number(fd.get('hours_per_week'))})});renderLearningPath(d.roadmap);toast('Your personalised learning path is ready!');}
  catch(err){out.innerHTML=`<div class="learning-empty"><h2>Could not generate roadmap</h2><p>${escapeHtml(err.message)}</p></div>`;toast(err.message,true);}
  finally{btn.disabled=false;btn.textContent='Generate my learning path ↗';}
});

async function loadAnalyzerContext(){
  const box=$('#analyzerProfileContext');
  if(!box)return;
  if(!currentUser){box.textContent='Log in to include your saved teach/learn skills automatically.';return;}
  const known=[...skills(currentUser.teach),...skills(currentUser.learn)];
  box.innerHTML=`<strong>Profile skills included automatically</strong><span>${known.length?known.map(escapeHtml).join(', '):'No skills saved yet — add skills in My profile or type them above.'}</span>`;
}
function renderSkillAnalysis(a){
  const out=$('#skillAnalyzerOutput');
  const strengths=(a.strengths||[]).map(x=>`<span class="analysis-skill good">✓ ${escapeHtml(x.skill)}</span>`).join('')||'<p class="muted">No mapped competencies matched yet. Add skills you already know to get a more accurate result.</p>';
  const gaps=(a.gaps||[]).map(x=>`<article class="gap-item"><div class="gap-item-top"><strong>${escapeHtml(x.skill)}</strong><span class="gap-priority ${x.priority.toLowerCase()}">${escapeHtml(x.priority)} priority</span></div><p>${escapeHtml(x.reason)}</p><div class="gap-action"><b>Suggested action:</b> ${escapeHtml(x.action)}</div></article>`).join('')||'<div class="success-note">Great work — all competencies in this role map matched skills you supplied. Consider building a portfolio project to validate them.</div>';
  const steps=(a.next_steps||[]).map(x=>`<div class="analysis-next-step"><span>${x.step}</span><div><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.detail)}</p></div></div>`).join('');
  const mentors=(a.mentor_suggestions||[]).map(m=>`<div class="analysis-mentor"><div><strong>${escapeHtml(m.name)}</strong><small>${escapeHtml(m.department||'SkillSwap member')}</small><div class="skill-tags">${m.skills.map(x=>`<span class="skill-tag">${escapeHtml(x)}</span>`).join('')}</div></div><button class="secondary-button" type="button" data-analyzer-mentor="${m.id}" data-name="${escapeHtml(m.name)}" data-skill="${escapeHtml(m.skills[0]||'')}">View in Discover</button></div>`).join('');
  out.innerHTML=`<div class="analysis-summary"><div><div class="eyebrow">YOUR SKILL COVERAGE</div><h2>${escapeHtml(a.goal)}</h2><p>${escapeHtml(a.level)} · ${a.matched_count} of ${a.required_count} mapped competencies matched</p></div><div class="analysis-score"><strong>${a.coverage}%</strong><span>coverage</span></div><div class="analysis-progress"><span style="width:${Math.max(0,Math.min(100,a.coverage))}%"></span></div></div><section class="analysis-section"><div class="analysis-section-head"><div><div class="eyebrow">WHAT YOU ALREADY KNOW</div><h2>Your strengths</h2></div><span class="analysis-count">${a.matched_count} matched</span></div><div class="analysis-skills">${strengths}</div></section><section class="analysis-section"><div class="analysis-section-head"><div><div class="eyebrow">OPPORTUNITIES TO GROW</div><h2>Missing skills</h2></div><span class="analysis-count">${a.missing_count} gaps</span></div><div class="gap-list">${gaps}</div></section>${steps?`<section class="analysis-section"><div class="eyebrow">YOUR ACTION PLAN</div><h2>Recommended next steps</h2><div class="analysis-steps">${steps}</div></section>`:''}${mentors?`<section class="analysis-section"><div class="eyebrow">LEARN WITH THE COMMUNITY</div><h2>Potential SkillSwap mentors</h2><div class="analysis-mentors">${mentors}</div></section>`:''}<div class="roadmap-engine-note"><strong>Method:</strong> ${escapeHtml(a.method)}. ${escapeHtml(a.note)}</div>`;
  out.querySelectorAll('[data-analyzer-mentor]').forEach(b=>b.addEventListener('click',()=>{showView('discover');$('#profileSearch').value=b.dataset.skill;loadProfiles()}));
}
$('#skillAnalyzerForm')?.addEventListener('submit',async e=>{
  e.preventDefault();if(!currentUser){toast('Please log in to analyze your profile skills.',true);openAuth('login');return;}
  const form=e.currentTarget,btn=$('#analyzeSkillsBtn'),out=$('#skillAnalyzerOutput');btn.disabled=true;btn.textContent='Analyzing your skills…';out.innerHTML='<div class="learning-empty"><span class="learning-spinner">✧</span><h2>Comparing your competencies</h2><p>Checking your profile against the target role skill map…</p></div>';
  try{const fd=new FormData(form);const d=await api('/api/skill-analyzer',{method:'POST',body:JSON.stringify({goal:fd.get('goal'),level:fd.get('level'),current_skills:fd.get('current_skills')})});renderSkillAnalysis(d.analysis);toast('Your skill gap analysis is ready.');}
  catch(err){out.innerHTML=`<div class="learning-empty"><h2>Could not analyze skills</h2><p>${escapeHtml(err.message)}</p></div>`;toast(err.message,true);}
  finally{btn.disabled=false;btn.textContent='Analyze my skill gaps ↗';}
});


function renderFeedbackAnalysis(data){
  const out=$('#feedbackAnalyzerOutput');
  if(!data.total){out.innerHTML=`<div class="feedback-empty"><div class="feedback-empty-icon">◉</div><h2>No feedback to analyse yet</h2><p>${escapeHtml(data.summary)}</p><div class="feedback-empty-steps"><span>1. Complete a skill exchange</span><span>2. Ask your partner to rate the session</span><span>3. Return here to view sentiment insights</span></div></div>`;return;}
  const dist=data.distribution||{};
  const cards=[['Positive',dist.Positive||0,'positive'],['Neutral',dist.Neutral||0,'neutral'],['Negative',dist.Negative||0,'negative']];
  const reviews=(data.reviews||[]).map(r=>`<article class="feedback-review"><div class="feedback-review-top"><span class="feedback-sentiment ${r.sentiment.toLowerCase()}">${escapeHtml(r.sentiment)}</span><span class="feedback-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><small>${r.created_at?new Date(r.created_at).toLocaleDateString():''}</small></div><p>${escapeHtml(r.comment||'No written comment was provided.')}</p><div class="feedback-review-meta"><span>Text score: ${Number(r.sentiment_score).toFixed(2)}</span><span>Estimate confidence: ${r.confidence}%</span>${(r.aspects||[]).map(a=>`<span>${escapeHtml(a.aspect)}</span>`).join('')}</div></article>`).join('');
  const aspects=(data.top_aspects||[]).map(a=>`<div class="feedback-aspect"><span>${escapeHtml(a.aspect)}</span><b>${a.mentions} mention${a.mentions===1?'':'s'}</b></div>`).join('')||'<p class="muted">No recurring themes identified yet. Written comments will help surface themes.</p>';
  out.innerHTML=`<div class="feedback-summary-grid"><article class="feedback-stat-card"><span>REVIEWS RECEIVED</span><strong>${data.total}</strong><small>From completed exchanges</small></article><article class="feedback-stat-card"><span>AVERAGE RATING</span><strong>${data.average_rating??'—'}<i>/5</i></strong><small>Across your received reviews</small></article><article class="feedback-stat-card"><span>POSITIVE SENTIMENT</span><strong>${data.positive_rate}%</strong><small>${dist.Positive||0} positive review${(dist.Positive||0)===1?'':'s'}</small></article><article class="feedback-stat-card"><span>NEGATIVE SENTIMENT</span><strong>${data.negative_rate}%</strong><small>${dist.Negative||0} review${(dist.Negative||0)===1?'':'s'} to learn from</small></article></div><div class="feedback-insight-banner"><strong>Overall insight</strong><p>${escapeHtml(data.summary)}</p></div><div class="feedback-analysis-grid"><section class="feedback-panel"><div class="eyebrow">SENTIMENT DISTRIBUTION</div><h2>How learners feel</h2><div class="feedback-dist">${cards.map(c=>`<div class="feedback-dist-row"><div><span>${c[0]}</span><b>${c[1]}</b></div><div class="feedback-dist-track"><i class="${c[2]}" style="width:${data.total?Math.round(c[1]*100/data.total):0}%"></i></div></div>`).join('')}</div></section><section class="feedback-panel"><div class="eyebrow">RECURRING THEMES</div><h2>What feedback mentions</h2><div class="feedback-aspects">${aspects}</div></section></div><section class="feedback-reviews-section"><div class="eyebrow">YOUR RECEIVED REVIEWS</div><h2>Review-by-review analysis</h2><div class="feedback-reviews">${reviews}</div></section><div class="roadmap-engine-note"><strong>Analysis method:</strong> ${escapeHtml(data.method)} Sentiment is an estimate, not an objective judgement of a person.</div>`;
}
async function loadFeedbackAnalysis(){
  const out=$('#feedbackAnalyzerOutput'),notice=$('#feedbackAnalyzerNotice');
  if(!currentUser){notice.textContent='Log in to analyse feedback received on your completed skill exchanges.';out.innerHTML='<div class="learning-empty"><h2>Log in to view your feedback</h2><p>Your personal feedback dashboard is available after you sign in.</p><button class="primary-button" id="feedbackLoginBtn">Log in ↗</button></div>';$('#feedbackLoginBtn')?.addEventListener('click',()=>openAuth('login'));return;}
  notice.textContent='Analysing reviews received by '+currentUser.name+'.';out.innerHTML='<div class="learning-empty"><span class="learning-spinner">◉</span><h2>Analysing your feedback</h2><p>Reading review text, ratings and recurring themes…</p></div>';
  try{const data=await api('/api/feedback/analyzer');renderFeedbackAnalysis(data);notice.textContent=`Private analysis of ${data.total} review${data.total===1?'':'s'} received by your account.`;}
  catch(err){out.innerHTML=`<div class="learning-empty"><h2>Could not load feedback</h2><p>${escapeHtml(err.message)}</p></div>`;notice.textContent=err.message;}
}
$('#refreshFeedbackAnalysis')?.addEventListener('click',loadFeedbackAnalysis);
$('#feedbackTextForm')?.addEventListener('submit',async e=>{
  e.preventDefault();if(!currentUser){openAuth('login');return;}
  const form=e.currentTarget,btn=$('#analyzeFeedbackTextBtn'),result=$('#feedbackTextResult');btn.disabled=true;btn.textContent='Analysing…';result.innerHTML='<p class="muted">Checking sentiment and feedback themes…</p>';
  try{const fd=new FormData(form);const d=await api('/api/feedback/analyze-text',{method:'POST',body:JSON.stringify({comment:fd.get('comment'),rating:Number(fd.get('rating'))})});const tone=d.sentiment.toLowerCase();result.innerHTML=`<div class="feedback-preview-card"><div class="feedback-review-top"><span class="feedback-sentiment ${tone}">${escapeHtml(d.sentiment)} sentiment</span><strong>${d.confidence}% confidence estimate</strong></div><div class="feedback-preview-score">Sentiment score: ${Number(d.score).toFixed(2)} <small>(-1 negative · 0 neutral · +1 positive)</small></div><p>${(d.evidence||[]).length?'Detected terms: '+d.evidence.map(escapeHtml).join(', '):'No strong sentiment words detected; star rating has more influence.'}</p><div class="feedback-review-meta">${(d.aspects||[]).map(a=>`<span>${escapeHtml(a.aspect)}: ${a.mentions.map(escapeHtml).join(', ')}</span>`).join('')||'<span>No specific feedback theme detected</span>'}</div><small>${escapeHtml(d.note)}</small></div>`;}
  catch(err){result.innerHTML=`<p class="error-note">${escapeHtml(err.message)}</p>`;}
  finally{btn.disabled=false;btn.textContent='Analyze sentiment ↗';}
});

(async function init(){
  const started=performance.now();
  try{await refreshMe();if(currentUser){await Promise.all([loadMatches(),loadSwaps()]);updateUserUI()}else{updateUserUI()}}
  catch(err){console.error('SkillSwap startup:',err);toast('Some information could not be refreshed. You can still explore SkillSwap.',true)}
  finally{const elapsed=performance.now()-started;const minimum=window.matchMedia('(prefers-reduced-motion: reduce)').matches?250:950;setTimeout(hideSiteLoader,Math.max(0,minimum-elapsed))}
})();
